  "python": "def pilot_policy(trace):
    if not trace:
        return None
    last_item = trace[-1]
    action = last_item[0]
    label = last_item[1]

    if action.name == 'broker/prepare':
        return None
    elif action.name == 'locks/issue':
        params = json.loads(action.arguments)
        target = params.get('target')
        if target == 'sms':
            allowed = {'ACCESS_CODE'}
            if not label.subset.issubset(allowed):
                raise PolicyViolation('sms allows only ACCESS_CODE')
            return None
        elif target == 'visit':
            return None
        else:
            raise PolicyViolation('Invalid target for locks/issue')
    elif action.name == 'broker/send':
        params = json.loads(action.arguments)
        target = params.get('target')
        if target == 'listing':
            allowed = {'PII', 'ACCESS_CODE'}
            if not label.subset.issubset(allowed):
                raise PolicyViolation('listing allows only PII and ACCESS_CODE')
            return None
        elif target == 'sms':
            allowed = {'ACCESS_CODE'}
            if not label.subset.issubset(allowed):
                raise PolicyViolation('sms allows only ACCESS_CODE')
            return None
        elif target == 'private':
            return None
        else:
            raise PolicyViolation('Invalid target for broker/send')
    else:
        raise PolicyViolation('Unknown action name')"
